import{_ as o,I as B,c as i,o as r,a3 as a,b as c,w as E,a as l,J as A,a4 as s}from"./chunks/framework.BusRvirq.js";const u=JSON.parse('{"title":"초저지연 실시간 화면 미러링 및 비동기 듀얼-트랙 캡처","description":"Direct MJPEG 기반 60 FPS 화면 스트리밍과 UI 프리징을 방지하는 비동기 듀얼-트랙 사용자 이벤트 레코딩 메커니즘","frontmatter":{"title":"초저지연 실시간 화면 미러링 및 비동기 듀얼-트랙 캡처","shortTitle":"초저지연 미러링 & 캡처","category":"모바일 테스트 엔지니어링","sort":22,"description":"Direct MJPEG 기반 60 FPS 화면 스트리밍과 UI 프리징을 방지하는 비동기 듀얼-트랙 사용자 이벤트 레코딩 메커니즘","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/synceta/mobile-live-mirroring.html"}]]},"headers":[],"relativePath":"synceta/mobile-live-mirroring.md","filePath":"ko/synceta/mobile-live-mirroring.md","lastUpdated":1791239682000}'),n={name:"synceta/mobile-live-mirroring.md"};function d(C,e,D,m,h,g){const t=B("Mermaid");return r(),i("div",null,[e[1]||(e[1]=a('<h1 id="초저지연-실시간-화면-미러링-및-비동기-듀얼-트랙-캡처" tabindex="-1">초저지연 실시간 화면 미러링 및 비동기 듀얼-트랙 캡처 <a class="header-anchor" href="#초저지연-실시간-화면-미러링-및-비동기-듀얼-트랙-캡처" aria-label="Permalink to “초저지연 실시간 화면 미러링 및 비동기 듀얼-트랙 캡처”">​</a></h1><h2 id="_1-개요-및-지연시간-병목-해결" tabindex="-1">1. 개요 및 지연시간 병목 해결 <a class="header-anchor" href="#_1-개요-및-지연시간-병목-해결" aria-label="Permalink to “1. 개요 및 지연시간 병목 해결”">​</a></h2><p>원격 또는 로컬 USB로 연결된 모바일 단말기를 PC 화면에서 보며 마우스로 조작하는 레코딩 환경에서는 <strong>화면 전송 지연(Latency)</strong>과 <strong>터치 반응 속도</strong>가 사용자 경험의 핵심입니다.</p><p>기존의 단순 프레임 캡처 방식(ADB <code>screencap</code> 반복 호출 및 Electron IPC 버퍼 복사)은 다음과 같은 병목이 있었습니다:</p><ol><li><strong>높은 화면 전송 지연</strong>: 프레임당 100~200ms 이상의 지연이 누적되어 빠른 스크롤이나 타이핑 시 화면이 심하게 밀리는 현상.</li><li><strong>동기식 XML 덤프에 따른 UI 프리징</strong>: 사용자가 화면을 터치할 때마다 단말기의 접근성 XML 트리를 동기식으로 추출(<code>getPageSource</code>)하느라 수백 밀리초 동안 화면 입력이 멈추는 현상.</li><li><strong>합성 이벤트 중복 기록</strong>: 모바일 브라우저/웹뷰 환경에서 단일 터치 시 발생하는 <code>touchstart</code>, <code>touchend</code>와 브라우저가 자동 생성하는 가상 <code>click</code> 이벤트가 2중, 3중으로 중복 기록되는 결함.</li></ol><p><code>SyncETA</code>는 <strong>Direct MJPEG 스트리밍 파이프라인</strong>과 <strong>비동기 듀얼-트랙 캡처 아키텍처</strong>를 통해 이 세 가지 병목을 해결하였습니다.</p>',6)),(r(),c(s,null,{default:E(()=>[A(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20DeviceServer%20%5B%22%EB%8B%A8%EB%A7%90%EA%B8%B0%20%EC%83%81%EC%A3%BC%20%EB%8D%B0%EB%AA%AC%20(WDA%20%2F%20UiAutomator2)%22%5D%0A%20%20%20%20%20%20%20%20StreamPort%5B%22HTTP%20MJPEG%20%EC%8A%A4%ED%8A%B8%EB%A6%AC%EB%B0%8D%20%ED%8F%AC%ED%8A%B8%20(7810%20%2F%209100)%22%5D%0A%20%20%20%20%20%20%20%20TouchPort%5B%22WebDriver%20%EC%A0%9C%EC%96%B4%20%ED%8F%AC%ED%8A%B8%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20FrontendUI%20%5B%22%ED%94%84%EB%A1%A0%ED%8A%B8%EC%97%94%EB%93%9C%20%EB%AF%B8%EB%9F%AC%EB%A7%81%20%EB%B7%B0%EC%96%B4%20(Vue%203%20Client)%22%5D%0A%20%20%20%20%20%20%20%20ImgView%5B%22HTML5%20%3Cimg%3E%20%ED%83%9C%EA%B7%B8%20(Direct%20HTTP%20%EC%86%8C%EB%B9%84)%22%5D%0A%20%20%20%20%20%20%20%20MouseCapture%5B%22%EB%A7%88%EC%9A%B0%EC%8A%A4%20%ED%81%B4%EB%A6%AD%2F%EB%93%9C%EB%9E%98%EA%B7%B8%20%EB%A6%AC%EC%8A%A4%EB%84%88%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20AsyncPipeline%20%5B%22%EB%B9%84%EB%8F%99%EA%B8%B0%20%EB%93%80%EC%96%BC-%ED%8A%B8%EB%9E%99%20%EC%B2%98%EB%A6%AC%20%ED%8C%8C%EC%9D%B4%ED%94%84%EB%9D%BC%EC%9D%B8%22%5D%0A%20%20%20%20%20%20%20%20FastTrack%5B%22%5B%ED%8A%B8%EB%9E%99%201%3A%20%EC%A6%89%EA%B0%81%20%EB%B0%98%EC%9D%91%5D%3Cbr%2F%3E%EC%A0%95%EA%B7%9C%ED%99%94%20%EC%A2%8C%ED%91%9C%20%EC%A6%89%EC%8B%9C%20%ED%84%B0%EC%B9%98%20%EC%A3%BC%EC%9E%85%22%5D%0A%20%20%20%20%20%20%20%20SlowTrack%5B%22%5B%ED%8A%B8%EB%9E%99%202%3A%20%EB%B9%84%EB%8F%99%EA%B8%B0%20%EB%A9%94%ED%83%80%EB%8D%B0%EC%9D%B4%ED%84%B0%5D%3Cbr%2F%3E%EB%B0%B1%EA%B7%B8%EB%9D%BC%EC%9A%B4%EB%93%9C%20XML%2FDOM%20%ED%8A%B8%EB%A6%AC%20%ED%8C%8C%EC%8B%B1%22%5D%0A%20%20%20%20%20%20%20%20Merge%5B%22%EB%A0%88%EC%BD%94%EB%93%9C%20%ED%95%A9%EC%84%B1%EA%B8%B0%20%EB%B0%8F%20300ms%20%EB%94%94%EB%B0%94%EC%9A%B4%EC%8A%A4%20%ED%95%84%ED%84%B0%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20StreamPort%20--%3E%20%7CDirect%20MJPEG%20%EB%AC%B4%EB%B3%B5%EC%82%AC%20%EC%8A%A4%ED%8A%B8%EB%A6%BC%20(15ms%20%EB%AF%B8%EB%A7%8C)%7C%20ImgView%0A%20%20%20%20MouseCapture%20--%3E%20FastTrack%20--%3E%20TouchPort%0A%20%20%20%20MouseCapture%20--%3E%20SlowTrack%20--%3E%20Merge%0A%20%20%20%20Merge%20--%3E%20StoredRecord%5B%22%EC%A0%95%EA%B7%9C%ED%99%94%EB%90%9C%20%EC%8B%9C%EB%82%98%EB%A6%AC%EC%98%A4%20%EB%A0%88%EC%BD%94%EB%93%9C%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_2-direct-mjpeg-초저지연-스트리밍-아키텍처" tabindex="-1">2. Direct MJPEG 초저지연 스트리밍 아키텍처 <a class="header-anchor" href="#_2-direct-mjpeg-초저지연-스트리밍-아키텍처" aria-label="Permalink to “2. Direct MJPEG 초저지연 스트리밍 아키텍처”">​</a></h2><p>Electron 메인 프로세스를 거쳐 렌더러 프로세스로 대용량 이미지 버퍼를 복사(IPC Transfer)하는 기존의 중간 다리 방식을 전면 개편하였습니다.</p><ul><li><strong>포트 포워딩 직접 바인딩</strong>: <ul><li>Android의 경우 UiAutomator2의 내장 스트리밍 포트(기본 7810)를 로컬 포트로 포워딩합니다.</li><li>iOS의 경우 WebDriverAgent의 MJPEG 서버 포트(기본 9100)를 로컬 포트로 포워딩합니다.</li></ul></li><li><strong>클라이언트 직접 소비</strong>: <ul><li>프론트엔드 뷰어(<code>MobileLiveMirrorViewer.vue</code>)는 로컬 포워딩된 <code>http://127.0.0.1:7810</code> 엔드포인트를 표준 <code>&lt;img&gt;</code> 태그의 <code>src</code>로 직접 소비합니다.</li><li>별도의 바이너리 파싱이나 IPC 메모리 복사 오버헤드가 발생하지 않으므로, <strong>초당 60 프레임(60 FPS) 및 실측 지연시간 15밀리초(ms) 미만</strong>의 렌더링 성능을 유지합니다.</li></ul></li></ul><hr><h2 id="_3-비동기-듀얼-트랙-이벤트-캡처-메커니즘" tabindex="-1">3. 비동기 듀얼-트랙 이벤트 캡처 메커니즘 <a class="header-anchor" href="#_3-비동기-듀얼-트랙-이벤트-캡처-메커니즘" aria-label="Permalink to “3. 비동기 듀얼-트랙 이벤트 캡처 메커니즘”">​</a></h2><p>터치 입력과 무거운 메타데이터 추출 작업을 두 개의 독립된 비동기 트랙으로 분리하여 조작 감도를 유지합니다.</p><h3 id="트랙-1-고속-주입-트랙-fast-track" tabindex="-1">트랙 1: 고속 주입 트랙 (Fast Track) <a class="header-anchor" href="#트랙-1-고속-주입-트랙-fast-track" aria-label="Permalink to “트랙 1: 고속 주입 트랙 (Fast Track)”">​</a></h3><ul><li>사용자가 마우스를 클릭하는 즉시, 화면 뷰포트 대비 상대 좌표(0.0~1.0)를 산출하여 단말기로 전송합니다.</li><li>단말기 화면에 터치 피드백이 지연 없이 즉각 반영되므로 사용자는 실제 기기를 직접 터치하는 것과 동일한 반응 속도를 체감합니다.</li></ul><h3 id="트랙-2-비동기-메타데이터-추출-트랙-metadata-track" tabindex="-1">트랙 2: 비동기 메타데이터 추출 트랙 (Metadata Track) <a class="header-anchor" href="#트랙-2-비동기-메타데이터-추출-트랙-metadata-track" aria-label="Permalink to “트랙 2: 비동기 메타데이터 추출 트랙 (Metadata Track)”">​</a></h3><ul><li>터치가 주입된 직후 백그라운드 비동기 워커가 현재 화면의 접근성 트리(Accessibility Hierarchy) 및 DOM 노드 정보를 수집합니다.</li><li>수집된 속성(<code>resourceId</code>, <code>className</code>, 텍스트 값, 시각 앵커 바운딩 박스)은 트랙 1에서 기록된 좌표 정보와 사후 병합되어 완전한 시나리오 카드로 저장됩니다.</li></ul><hr><h2 id="_4-합성-이벤트-디바운스-및-중복-방지-필터" tabindex="-1">4. 합성 이벤트 디바운스 및 중복 방지 필터 <a class="header-anchor" href="#_4-합성-이벤트-디바운스-및-중복-방지-필터" aria-label="Permalink to “4. 합성 이벤트 디바운스 및 중복 방지 필터”">​</a></h2><p>모바일 웹뷰 및 브라우저 환경에서 단일 탭 동작 시 브라우저 렌더러 엔진은 터치 호환성을 위해 <code>touchstart</code>, <code>touchend</code> 이벤트에 이어 약 300ms 이후 인위적인 합성 <code>click</code> 이벤트를 발생시킵니다.</p><p><code>SyncETA</code>는 이러한 중복 기록을 방지하기 위해 <strong>300ms 슬라이딩 윈도우 디바운스 필터</strong>를 적용합니다:</p><ul><li>직전 터치 이벤트와 동일한 좌표 반경(±5px 이내)에서 300ms 이내에 발생하는 후속 클릭 이벤트는 기록 목록에서 자동 소거됩니다.</li><li>이를 통해 시나리오 재실행 시 동일 버튼이 2회 연속 클릭되어 의도치 않은 중복 결제나 화면 닫힘이 발생하는 문제를 사전에 방지합니다.</li></ul>',16))])}const _=o(n,[["render",d]]);export{u as __pageData,_ as default};
